        assert!(ctx.allow_rules().is_empty());
        assert!(ctx.guard_rules().is_empty());
        assert!(ctx.extra_secrets().is_empty());
        assert!(ctx.permission_policy().is_none());
        assert!(ctx.approval_handler().is_none());
    }

